import { createHash } from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import type { IdeTarget } from "../schema/team.js";

export const GENERATED_MARKER_PREFIX =
  "<!-- GENERATED BY agent-studio sync — DO NOT EDIT DIRECTLY; edit .agent-team/ instead.";
export const MANAGED_BEGIN = "<!-- agent-studio:begin -->";
export const MANAGED_END = "<!-- agent-studio:end -->";
export const HOOK_TAG_NEEDLE = "agent-studio hook-emit";

const GENERATED_MARKER_REGEX =
  /^<!-- GENERATED BY agent-studio sync — DO NOT EDIT DIRECTLY; edit \.agent-team\/ instead\. hash:sha256:([0-9a-f]{64}) -->$/m;

export function normalizeLf(text: string): string {
  return text.replace(/\r\n/g, "\n").replace(/\r/g, "\n");
}

export function sha256Hex(content: string): string {
  return createHash("sha256").update(normalizeLf(content), "utf8").digest("hex");
}

export function formatGeneratedMarker(canonicalContent: string): string {
  const hash = sha256Hex(canonicalContent);
  return `${GENERATED_MARKER_PREFIX} hash:sha256:${hash} -->`;
}

export function extractGeneratedHash(text: string): string | null {
  const match = normalizeLf(text).match(GENERATED_MARKER_REGEX);
  return match?.[1] ?? null;
}

/**
 * Wraps generated Markdown with a deterministic SHA-256 marker comment.
 * When `frontmatter` is provided, the marker is placed immediately after the
 * closing `---` so IDE frontmatter parsers still see `---` on line 1.
 */
export function wrapGeneratedMarkdown(
  body: string,
  frontmatter?: string,
): string {
  const cleanBody = normalizeLf(body).replace(/^\n+/, "").trimEnd();
  if (frontmatter && frontmatter.trim().length > 0) {
    const cleanFm = normalizeLf(frontmatter).trim();
    const canonical = `---\n${cleanFm}\n---\n\n${cleanBody}\n`;
    const marker = formatGeneratedMarker(canonical);
    return `---\n${cleanFm}\n---\n${marker}\n\n${cleanBody}\n`;
  }
  const canonical = `${cleanBody}\n`;
  const marker = formatGeneratedMarker(canonical);
  return `${marker}\n\n${cleanBody}\n`;
}

/**
 * Verifies that a generated Markdown file's embedded SHA-256 marker matches
 * its current content (detects manual edits even without comparing to source).
 */
export function verifyGeneratedMarkdownHash(text: string): boolean {
  const normalized = normalizeLf(text);
  const embedded = extractGeneratedHash(normalized);
  if (!embedded) return false;

  // Managed markdown block: `<!-- agent-studio:begin -->\n<!-- GENERATED ... -->\n\n<body...>\n<!-- agent-studio:end -->`
  if (
    normalized.startsWith(`${MANAGED_BEGIN}\n`) &&
    normalized.endsWith(MANAGED_END)
  ) {
    const inner = normalized.slice(
      `${MANAGED_BEGIN}\n`.length,
      normalized.length - MANAGED_END.length,
    );
    const body = inner.replace(
      /^<!-- GENERATED BY agent-studio sync — DO NOT EDIT DIRECTLY; edit \.agent-team\/ instead\. hash:sha256:[0-9a-f]{64} -->\n\n/,
      "",
    );
    if (body !== inner && sha256Hex(body) === embedded) {
      return true;
    }
  }

  // Frontmatter-less generated markdown places the marker on line 1 followed by `\n\n`
  // (canonical hash is computed over `${cleanBody}\n` without a leading blank line).
  // Also allow a single `\n` separator after the marker for backward compatibility.
  if (normalized.startsWith(GENERATED_MARKER_PREFIX)) {
    const afterDouble = normalized.replace(
      /^<!-- GENERATED BY agent-studio sync — DO NOT EDIT DIRECTLY; edit \.agent-team\/ instead\. hash:sha256:[0-9a-f]{64} -->\n\n/,
      "",
    );
    if (afterDouble !== normalized && sha256Hex(afterDouble) === embedded) {
      return true;
    }
    const afterSingle = normalized.replace(
      /^<!-- GENERATED BY agent-studio sync — DO NOT EDIT DIRECTLY; edit \.agent-team\/ instead\. hash:sha256:[0-9a-f]{64} -->\n/,
      "",
    );
    return afterSingle !== normalized && sha256Hex(afterSingle) === embedded;
  }

  const withoutMarker = normalized.replace(
    /^<!-- GENERATED BY agent-studio sync — DO NOT EDIT DIRECTLY; edit \.agent-team\/ instead\. hash:sha256:[0-9a-f]{64} -->\n/m,
    "",
  );
  return sha256Hex(withoutMarker) === embedded;
}

export function renderManagedMarkdownBlock(blockContent: string): string {
  const cleanBlock = normalizeLf(blockContent).trim();
  const marker = formatGeneratedMarker(`${cleanBlock}\n`);
  return `${MANAGED_BEGIN}\n${marker}\n\n${cleanBlock}\n${MANAGED_END}`;
}

/**
 * Inserts or replaces ONLY the `<!-- agent-studio:begin --> ... <!-- agent-studio:end -->`
 * managed section while preserving all user-written Markdown above and below.
 */
export function mergeManagedMarkdownBlock(
  existing: string | null | undefined,
  blockContent: string,
): string {
  const renderedBlock = renderManagedMarkdownBlock(blockContent);
  if (!existing || existing.trim().length === 0) {
    return `${renderedBlock}\n`;
  }

  const normalized = normalizeLf(existing);
  const beginIdx = normalized.indexOf(MANAGED_BEGIN);
  const endIdx = normalized.indexOf(MANAGED_END);

  if (beginIdx !== -1 && endIdx !== -1 && endIdx > beginIdx) {
    const before = normalized.slice(0, beginIdx);
    const after = normalized.slice(endIdx + MANAGED_END.length);
    const merged = `${before}${renderedBlock}${after}`;
    return merged.endsWith("\n") ? merged : `${merged}\n`;
  }

  const trimmedExisting = normalized.replace(/\n+$/, "");
  return `${trimmedExisting}\n\n${renderedBlock}\n`;
}

export function extractManagedMarkdownBlock(text: string): string | null {
  const normalized = normalizeLf(text);
  const beginIdx = normalized.indexOf(MANAGED_BEGIN);
  const endIdx = normalized.indexOf(MANAGED_END);
  if (beginIdx === -1 || endIdx === -1 || endIdx <= beginIdx) {
    return null;
  }
  return normalized.slice(beginIdx, endIdx + MANAGED_END.length);
}

export interface HookCommandSpec {
  type: "command";
  command: string;
  timeout?: number;
}

export interface ClaudeHookRule {
  matcher?: string;
  hooks: HookCommandSpec[];
}

export interface CopilotHookRule {
  type: "command";
  command: string;
  timeoutSec?: number;
}

export type HookRuleEntry = ClaudeHookRule | CopilotHookRule;

export interface JsonMergePatch {
  mcpServers?: Record<string, unknown>;
  servers?: Record<string, unknown>;
  hooks?: Record<string, HookRuleEntry[]>;
  scopedEntries?: Record<string, Record<string, unknown>>;
  topLevelDefaults?: Record<string, unknown>;
  removeTopLevelIfEqual?: Record<string, unknown>;
  pruneManagedHookEvents?: readonly string[];
}

function isPlainObject(val: unknown): val is Record<string, unknown> {
  return Boolean(val) && typeof val === "object" && !Array.isArray(val);
}

function deepClone<T>(val: T): T {
  return JSON.parse(JSON.stringify(val)) as T;
}

export function isManagedHookEntry(entry: unknown): boolean {
  if (!isPlainObject(entry)) return false;
  if (entry._managedBy === "agent-studio") return true;
  if (typeof entry.command === "string" && entry.command.includes(HOOK_TAG_NEEDLE)) {
    return true;
  }
  if (Array.isArray(entry.hooks)) {
    return entry.hooks.some(
      (h) =>
        isPlainObject(h) &&
        typeof h.command === "string" &&
        h.command.includes(HOOK_TAG_NEEDLE),
    );
  }
  return false;
}

/**
 * Key-scoped non-destructive JSON merger.
 * Updates ONLY the targeted `agent-studio` MCP server entries, scoped object keys,
 * and tagged `agent-studio` hook entries—preserving all pre-existing user MCP servers,
 * hooks, and settings untouched.
 */
export function mergeJsonKeyScoped(
  existingJson: Record<string, unknown> | null | undefined,
  patch: JsonMergePatch,
): Record<string, unknown> {
  const result: Record<string, unknown> = isPlainObject(existingJson)
    ? deepClone(existingJson)
    : {};

  if (patch.topLevelDefaults) {
    for (const [key, val] of Object.entries(patch.topLevelDefaults)) {
      if (!(key in result) || result[key] === undefined) {
        result[key] = deepClone(val);
      }
    }
  }

  if (patch.removeTopLevelIfEqual) {
    for (const [key, sentinel] of Object.entries(patch.removeTopLevelIfEqual)) {
      if (
        key in result &&
        stableStringify(result[key]) === stableStringify(sentinel)
      ) {
        delete result[key];
      }
    }
  }

  if (patch.mcpServers) {
    const existingServers = isPlainObject(result.mcpServers)
      ? { ...result.mcpServers }
      : {};
    for (const [key, val] of Object.entries(patch.mcpServers)) {
      existingServers[key] = deepClone(val);
    }
    result.mcpServers = existingServers;
  }

  if (patch.servers) {
    const existingServers = isPlainObject(result.servers)
      ? { ...result.servers }
      : {};
    for (const [key, val] of Object.entries(patch.servers)) {
      existingServers[key] = deepClone(val);
    }
    result.servers = existingServers;
  }

  if (
    (patch.pruneManagedHookEvents && patch.pruneManagedHookEvents.length > 0) ||
    patch.hooks
  ) {
    const existingHooks = isPlainObject(result.hooks)
      ? { ...result.hooks }
      : {};

    if (patch.pruneManagedHookEvents) {
      for (const legacyEvent of patch.pruneManagedHookEvents) {
        if (!Array.isArray(existingHooks[legacyEvent])) continue;
        const filtered = (existingHooks[legacyEvent] as unknown[]).filter(
          (entry) => !isManagedHookEntry(entry),
        );
        if (filtered.length === 0) {
          delete existingHooks[legacyEvent];
        } else {
          existingHooks[legacyEvent] = filtered;
        }
      }
    }

    if (patch.hooks) {
      for (const [eventName, managedRules] of Object.entries(patch.hooks)) {
        const currentList = Array.isArray(existingHooks[eventName])
          ? (existingHooks[eventName] as unknown[])
          : [];
        const preservedUserEntries = currentList.filter(
          (entry) => !isManagedHookEntry(entry),
        );
        existingHooks[eventName] = [
          ...preservedUserEntries,
          ...deepClone(managedRules),
        ];
      }
    }

    result.hooks = existingHooks;
  }

  if (patch.scopedEntries) {
    for (const [topKey, nestedPatch] of Object.entries(patch.scopedEntries)) {
      const existingSection = isPlainObject(result[topKey])
        ? { ...(result[topKey] as Record<string, unknown>) }
        : {};
      for (const [subKey, val] of Object.entries(nestedPatch)) {
        existingSection[subKey] = deepClone(val);
      }
      result[topKey] = existingSection;
    }
  }

  return result;
}

export type ExpectedFile =
  | {
      relPath: string;
      ide: IdeTarget;
      contributors?: IdeTarget[];
      kind: "generated";
      content: string;
    }
  | {
      relPath: string;
      ide: IdeTarget;
      contributors?: IdeTarget[];
      kind: "managed-markdown";
      blockContent: string;
    }
  | {
      relPath: string;
      ide: IdeTarget;
      contributors?: IdeTarget[];
      kind: "json-merge";
      patch: JsonMergePatch;
    };

function deepMergePlainObjects(
  base: Record<string, unknown>,
  incoming: Record<string, unknown>,
): Record<string, unknown> {
  const out: Record<string, unknown> = deepClone(base);
  for (const [k, v] of Object.entries(incoming)) {
    if (isPlainObject(v) && isPlainObject(out[k])) {
      out[k] = deepMergePlainObjects(out[k] as Record<string, unknown>, v);
    } else {
      out[k] = deepClone(v);
    }
  }
  return out;
}

function mergeKeyedPlainObjectMaps(
  a?: Record<string, unknown>,
  b?: Record<string, unknown>,
): Record<string, unknown> | undefined {
  if (!a && !b) return undefined;
  const out: Record<string, unknown> = a ? deepClone(a) : {};
  for (const [k, v] of Object.entries(b ?? {})) {
    if (isPlainObject(v) && isPlainObject(out[k])) {
      out[k] = deepMergePlainObjects(out[k] as Record<string, unknown>, v);
    } else {
      out[k] = deepClone(v);
    }
  }
  return out;
}

function mergeJsonMergePatches(
  a: JsonMergePatch,
  b: JsonMergePatch,
): JsonMergePatch {
  const mcpServers = mergeKeyedPlainObjectMaps(a.mcpServers, b.mcpServers);
  const servers = mergeKeyedPlainObjectMaps(a.servers, b.servers);

  let scopedEntries: Record<string, Record<string, unknown>> | undefined;
  if (a.scopedEntries || b.scopedEntries) {
    scopedEntries = {};
    for (const [topKey, subObj] of Object.entries(a.scopedEntries ?? {})) {
      scopedEntries[topKey] = deepClone(subObj);
    }
    for (const [topKey, subObj] of Object.entries(b.scopedEntries ?? {})) {
      scopedEntries[topKey] = mergeKeyedPlainObjectMaps(
        scopedEntries[topKey],
        subObj,
      ) as Record<string, unknown>;
    }
  }

  let topLevelDefaults: Record<string, unknown> | undefined;
  if (a.topLevelDefaults || b.topLevelDefaults) {
    topLevelDefaults = {
      ...(a.topLevelDefaults ? deepClone(a.topLevelDefaults) : {}),
      ...(b.topLevelDefaults ? deepClone(b.topLevelDefaults) : {}),
    };
  }

  let removeTopLevelIfEqual: Record<string, unknown> | undefined;
  if (a.removeTopLevelIfEqual || b.removeTopLevelIfEqual) {
    removeTopLevelIfEqual = {
      ...(a.removeTopLevelIfEqual ? deepClone(a.removeTopLevelIfEqual) : {}),
      ...(b.removeTopLevelIfEqual ? deepClone(b.removeTopLevelIfEqual) : {}),
    };
  }

  let pruneManagedHookEvents: string[] | undefined;
  if (a.pruneManagedHookEvents || b.pruneManagedHookEvents) {
    pruneManagedHookEvents = Array.from(
      new Set([
        ...(a.pruneManagedHookEvents ?? []),
        ...(b.pruneManagedHookEvents ?? []),
      ]),
    );
  }

  let hooks: Record<string, HookRuleEntry[]> | undefined;
  if (a.hooks || b.hooks) {
    hooks = {};
    for (const [ev, list] of Object.entries(a.hooks ?? {})) {
      hooks[ev] = deepClone(list);
    }
    for (const [ev, list] of Object.entries(b.hooks ?? {})) {
      const existing = hooks[ev] ?? [];
      const seen = new Set(existing.map((item) => stableStringify(item)));
      for (const item of list) {
        const key = stableStringify(item);
        if (!seen.has(key)) {
          seen.add(key);
          existing.push(deepClone(item));
        }
      }
      hooks[ev] = existing;
    }
  }

  return {
    ...(mcpServers ? { mcpServers } : {}),
    ...(servers ? { servers } : {}),
    ...(hooks ? { hooks } : {}),
    ...(scopedEntries ? { scopedEntries } : {}),
    ...(topLevelDefaults ? { topLevelDefaults } : {}),
    ...(removeTopLevelIfEqual ? { removeTopLevelIfEqual } : {}),
    ...(pruneManagedHookEvents ? { pruneManagedHookEvents } : {}),
  };
}

/**
 * Coalesces `ExpectedFile` entries of `kind === "json-merge"` sharing the same
 * normalized `relPath` (for example `.mcp.json` contributed by `claude-code`
 * and `copilot-vscode`) while retaining `contributors` for drift attribution.
 */
export function coalesceExpectedFiles(files: ExpectedFile[]): ExpectedFile[] {
  const out: ExpectedFile[] = [];
  const jsonMergeIdxByPath = new Map<string, number>();

  for (const file of files) {
    const normRel = file.relPath.replace(/\\/g, "/");
    if (file.kind !== "json-merge") {
      out.push(file);
      continue;
    }

    const existingIdx = jsonMergeIdxByPath.get(normRel);
    if (existingIdx === undefined) {
      jsonMergeIdxByPath.set(normRel, out.length);
      out.push({
        ...file,
        relPath: normRel,
        contributors: Array.from(new Set(file.contributors ?? [file.ide])),
      });
      continue;
    }

    const prev = out[existingIdx]!;
    if (prev.kind !== "json-merge") {
      out.push(file);
      continue;
    }
    const mergedContributors = Array.from(
      new Set([
        ...(prev.contributors ?? [prev.ide]),
        ...(file.contributors ?? [file.ide]),
      ]),
    );
    out[existingIdx] = {
      ...prev,
      contributors: mergedContributors,
      patch: mergeJsonMergePatches(prev.patch, file.patch),
    };
  }

  return out;
}

export interface DriftEntry {
  path: string;
  ide: IdeTarget;
  status: "missing" | "modified" | "out-of-date";
  reason: string;
}

export interface DriftReport {
  ok: boolean;
  checkedCount: number;
  entries: DriftEntry[];
}

function stableStringify(value: unknown): string {
  if (Array.isArray(value)) {
    return `[${value.map((v) => stableStringify(v)).join(",")}]`;
  }
  if (isPlainObject(value)) {
    const keys = Object.keys(value).sort();
    return `{${keys
      .map((k) => `${JSON.stringify(k)}:${stableStringify(value[k])}`)
      .join(",")}}`;
  }
  return JSON.stringify(value);
}

export function computeDrift(
  projectRoot: string,
  expectedFiles: ExpectedFile[],
): DriftReport {
  const root = path.resolve(projectRoot);
  const entries: DriftEntry[] = [];

  for (const expected of expectedFiles) {
    const absPath = path.join(root, expected.relPath);
    const normRel = expected.relPath.replace(/\\/g, "/");
    const targetIdes: IdeTarget[] =
      expected.contributors && expected.contributors.length > 0
        ? expected.contributors
        : [expected.ide];
    const pushDrift = (
      status: DriftEntry["status"],
      reason: string,
    ): void => {
      for (const ide of targetIdes) {
        entries.push({ path: normRel, ide, status, reason });
      }
    };

    if (!fs.existsSync(absPath)) {
      pushDrift("missing", "Expected compiled file does not exist.");
      continue;
    }

    const actualRaw = normalizeLf(fs.readFileSync(absPath, "utf8"));

    if (expected.kind === "generated") {
      const expectedNorm = normalizeLf(expected.content);
      if (actualRaw !== expectedNorm) {
        const hasMarker = extractGeneratedHash(actualRaw) !== null;
        const hashSelfValid = hasMarker
          ? verifyGeneratedMarkdownHash(actualRaw)
          : false;
        pushDrift(
          hasMarker && !hashSelfValid ? "modified" : "out-of-date",
          hasMarker && !hashSelfValid
            ? "Generated file was manually modified (SHA-256 marker mismatch)."
            : "Generated file is out of date with .agent-team/ source.",
        );
      }
      continue;
    }

    if (expected.kind === "managed-markdown") {
      const actualBlock = extractManagedMarkdownBlock(actualRaw);
      const expectedBlock = renderManagedMarkdownBlock(expected.blockContent);
      if (actualBlock === null) {
        pushDrift(
          "missing",
          "Managed <!-- agent-studio:begin/end --> block is missing from file.",
        );
      } else if (normalizeLf(actualBlock) !== normalizeLf(expectedBlock)) {
        const hashSelfValid = verifyGeneratedMarkdownHash(actualBlock);
        pushDrift(
          hashSelfValid ? "out-of-date" : "modified",
          hashSelfValid
            ? "Managed block is out of date with .agent-team/ source."
            : "Managed block was manually modified.",
        );
      }
      continue;
    }

    if (expected.kind === "json-merge") {
      let parsed: unknown;
      try {
        parsed = JSON.parse(actualRaw);
      } catch {
        pushDrift(
          "modified",
          "Target JSON file is malformed and cannot be parsed.",
        );
        continue;
      }
      if (!isPlainObject(parsed)) {
        pushDrift("modified", "Target JSON file root is not a JSON object.");
        continue;
      }
      const simulated = mergeJsonKeyScoped(parsed, expected.patch);
      if (stableStringify(parsed) !== stableStringify(simulated)) {
        pushDrift(
          "out-of-date",
          "Managed agent-studio JSON entries are missing or out of date.",
        );
      }
    }
  }

  return {
    ok: entries.length === 0,
    checkedCount: expectedFiles.length,
    entries,
  };
}
